begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
insert into public.courses(id,owner_id,title) values
 ('97000000-0000-0000-0000-000000000001','11111111-1111-1111-1111-111111111111','Summary course'),
 ('97000000-0000-0000-0000-000000000002','11111111-1111-1111-1111-111111111111','Empty');
set local role authenticated;
set local request.jwt.claims = '{"sub":"11111111-1111-1111-1111-111111111111","role":"authenticated"}';
select public.prepare_file_upload('97000000-0000-0000-0000-000000000001','97000000-0000-0000-0000-000000000010','a.txt','text/plain',10);
select public.prepare_file_upload('97000000-0000-0000-0000-000000000001','97000000-0000-0000-0000-000000000011','b.txt','text/plain',10);
select throws_ok($$select public.claim_summary()$$,'42501',null,'Clients cannot claim');
select throws_ok($$select * from public.summary_jobs$$,'42501',null,'Queue stays private');
select throws_ok($$select * from public.summary_requests$$,'42501',null,'Request mapping stays private');
reset role;
select public.complete_file_upload(id,'11111111-1111-1111-1111-111111111111') from public.files where course_id='97000000-0000-0000-0000-000000000001';
create temporary table sf as select d.id as document_id,m.id as material_id,m.file_id
 from public.source_documents d join public.materials m on m.id=d.material_id where m.course_id='97000000-0000-0000-0000-000000000001';
create temporary table cfg as select '{"version":"summary-v1","provider":"openai","model":"test","maxSourceCharacters":500000,"maxOutputTokens":3000,"maxCalls":200,"tokenBudget":2000000}'::jsonb as value;
create temporary table sj (id uuid, token uuid, summary_id uuid);
grant select,update,insert on sf,cfg,sj to authenticated,service_role;
select throws_ok($$select public.enqueue_summary('22222222-2222-2222-2222-222222222222',gen_random_uuid(),'course','97000000-0000-0000-0000-000000000001',(select value from cfg))$$,'P0002','TARGET_NOT_FOUND','Foreign target rejected');
select throws_ok($$select public.enqueue_summary('11111111-1111-1111-1111-111111111111',gen_random_uuid(),'course','97000000-0000-0000-0000-000000000002',(select value from cfg))$$,'22023','NO_SOURCES','Empty course rejected');
select throws_ok($$select public.enqueue_summary('11111111-1111-1111-1111-111111111111',gen_random_uuid(),'course','97000000-0000-0000-0000-000000000001',(select value from cfg))$$,'55000','SOURCES_NOT_READY','Incomplete course rejected');
update public.source_documents set processing_status='ready',completed_at=now(),extracted_text='Wichtiger Lerninhalt',pages='[{"page":1,"text":"Wichtiger Lerninhalt"}]' where id in(select document_id from sf);
select throws_ok($$select public.enqueue_summary('11111111-1111-1111-1111-111111111111',gen_random_uuid(),'course','97000000-0000-0000-0000-000000000001',(select value||'{"maxSourceCharacters":1}' from cfg))$$,'54000','SOURCE_LIMIT_EXCEEDED','Explicit input limit');
insert into sj(id) select (public.enqueue_summary('11111111-1111-1111-1111-111111111111','97000000-0000-0000-0000-000000000020','course','97000000-0000-0000-0000-000000000001',(select value from cfg))->>'job_id')::uuid;
select is((public.enqueue_summary('11111111-1111-1111-1111-111111111111','97000000-0000-0000-0000-000000000020','course','97000000-0000-0000-0000-000000000001',(select value from cfg))->>'job_id')::uuid,(select id from sj),'Network retry returns same job');
select is((public.enqueue_summary('11111111-1111-1111-1111-111111111111',gen_random_uuid(),'course','97000000-0000-0000-0000-000000000001',(select value from cfg))->>'job_id')::uuid,(select id from sj),'Different request deduplicates same sources');
select throws_ok($$select public.enqueue_summary('11111111-1111-1111-1111-111111111111','97000000-0000-0000-0000-000000000020','document',(select document_id from sf limit 1),(select value from cfg))$$,'22023','REQUEST_CONFLICT','Request payload conflict');
select is((select jsonb_array_length(sources) from public.summary_jobs where id=(select id from sj)),2,'Whole course captured');
select throws_ok($$select public.read_summary('22222222-2222-2222-2222-222222222222',(select id from sj))$$,'P0002','SUMMARY_NOT_FOUND','Foreign status hidden');
-- Keep this test independent of existing pending jobs in a developer database.
update public.summary_jobs set available_at=now()+interval '1 day' where id<>(select id from sj);
update sj set token=(public.claim_summary()->>'lease_token')::uuid;
select ok((select token is not null from sj),'Claim granted');
select is(public.claim_summary(),null::jsonb,'No duplicate active claim');
select is(public.reserve_summary_call((select id from sj),gen_random_uuid(),100),false,'Wrong lease cannot spend');
select is(public.reserve_summary_call((select id from sj),(select token from sj),100),true,'Budget reserved');
select is((select reserved_tokens from public.summary_jobs where id=(select id from sj)),100::bigint,'Cost is persisted before result');
select is(public.save_summary_step((select id from sj),gen_random_uuid(),'{}',1,2,'document'),false,'Wrong lease fenced');
select is(public.save_summary_step((select id from sj),(select token from sj),'{"partial":true}',1,2,'document'),true,'Partial checkpoint persisted');
select is((select checkpoint from public.summary_jobs where id=(select id from sj)),'{"partial":true}'::jsonb,'Checkpoint survives yield');
update sj set token=(public.claim_summary()->>'lease_token')::uuid;
update public.summary_jobs set lease_until=now()-interval '1 second' where id=(select id from sj);
select is(public.save_summary_step((select id from sj),(select token from sj),'{}',2,2,'completed','{"text":"late"}'),false,'Expired worker fenced');
update sj set token=(public.claim_summary()->>'lease_token')::uuid;
select is(public.save_summary_step((select id from sj),(select token from sj),'{}',2,2,'completed','{"version":1,"text":"Zusammenfassung","sections":[],"sources":[]}'),true,'Atomic publication');
update sj set summary_id=(select summary_id from public.summary_jobs where id=sj.id);
select is((public.read_summary('11111111-1111-1111-1111-111111111111',null,(select summary_id from sj))->>'is_stale')::boolean,false,'Fresh result');
select is((select generation_kind from public.summaries where id=(select summary_id from sj)),'course','Course kind explicit');
select is((public.enqueue_summary('11111111-1111-1111-1111-111111111111',gen_random_uuid(),'course','97000000-0000-0000-0000-000000000001',(select value from cfg))->>'summary_id')::uuid,(select summary_id from sj),'Completed result reused');
set local role authenticated;
select is((select count(*)::int from public.summary_generations where summary_id=(select summary_id from sj)),1,'Owner sees provenance');
select throws_ok($$update public.summary_generations set kind='document'$$,'42501',null,'Cannot forge provenance');
select throws_ok($$update public.summaries set generation_kind='manual'$$,'42501',null,'Cannot remove generated marker');
update public.summaries set content='{"text":"forged"}' where id=(select summary_id from sj);
select is((select content->>'text' from public.summaries where id=(select summary_id from sj)),'Zusammenfassung','Generated result read-only');
insert into public.materials(id,course_id,created_by,type,title) values('97000000-0000-0000-0000-000000000030','97000000-0000-0000-0000-000000000001',auth.uid(),'summary','Manual');
insert into public.summaries(material_id,content) values('97000000-0000-0000-0000-000000000030','{"text":"Manual"}');
update public.summaries set content='{"text":"Edited"}' where material_id='97000000-0000-0000-0000-000000000030';
select is((select content->>'text' from public.summaries where material_id='97000000-0000-0000-0000-000000000030'),'Edited','Manual edits preserved');
set local request.jwt.claims = '{"sub":"22222222-2222-2222-2222-222222222222","role":"authenticated"}';
select is((select count(*)::int from public.summary_generations where summary_id=(select summary_id from sj)),0,'Foreign provenance hidden');
select is((select count(*)::int from public.summaries where id=(select summary_id from sj)),0,'Foreign output hidden');
reset role;
update public.source_documents set extracted_text='Neuer Inhalt' where id=(select document_id from sf limit 1);
select is((public.read_summary('11111111-1111-1111-1111-111111111111',null,(select summary_id from sj))->>'is_stale')::boolean,true,'Source update marks result stale');
delete from sj;
insert into sj(id) select (public.enqueue_summary('11111111-1111-1111-1111-111111111111',gen_random_uuid(),'document',(select document_id from sf limit 1),(select value from cfg))->>'job_id')::uuid;
update sj set token=(public.claim_summary()->>'lease_token')::uuid;
update public.source_documents set extracted_text='Erneut verändert' where id=(select document_id from sf limit 1);
select is(public.save_summary_step((select id from sj),(select token from sj),'{}',1,1,'completed','{"text":"Stale"}'),true,'Source mutation handled');
select is((select error_code from public.summary_jobs where id=(select id from sj)),'SOURCE_CHANGED','Changed source cannot publish');
select throws_ok($$select public.retry_summary('11111111-1111-1111-1111-111111111111',(select id from sj))$$,'55000','NEW_REQUEST_REQUIRED','Changed source needs new snapshot');
delete from sj;
insert into sj(id) select (public.enqueue_summary('11111111-1111-1111-1111-111111111111',gen_random_uuid(),'document',(select document_id from sf limit 1),(select value||'{"tokenBudget":10}' from cfg))->>'job_id')::uuid;
update sj set token=(public.claim_summary()->>'lease_token')::uuid;
select is(public.reserve_summary_call((select id from sj),(select token from sj),11),false,'Budget cannot be exceeded');
select is((select error_code from public.summary_jobs where id=(select id from sj)),'BUDGET_EXCEEDED','Budget failure visible');
select throws_ok($$select public.retry_summary('11111111-1111-1111-1111-111111111111',(select id from sj))$$,'55000','NEW_REQUEST_REQUIRED','Retry cannot reset budget');
delete from public.courses where id='97000000-0000-0000-0000-000000000001';
select is((select count(*)::int from public.summary_jobs where course_id='97000000-0000-0000-0000-000000000001'),0,'Course deletion cascades jobs');
select * from finish();
rollback;
